const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Define Somalia geometry
    const somalia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
      .filter(ee.Filter.eq('country_na', 'Somalia'));
    const geom = somalia.geometry();

    // 2. Load CHIRPS rainfall data
    const chirps = ee.ImageCollection('USDOS/LSIB_SIMPLE/2017/CHIRPS/DAILY');

    // 3. Get 2022 March-September data
    const rainfall2022 = chirps
      .filter(ee.Filter.date('2022-03-01', '2022-10-01'))
      .select('precipitation');

    const size2022 = rainfall2022.size().getInfo();
    console.log(`2022 Images found: ${size2022}`);

    if (size2022 === 0) {
      console.log('No data for 2022 period.');
      console.log('<answer>C1</answer>');
      return;
    }

    // 4. Get historical average (1981-2021, March-September)
    const rainfallHistorical = chirps
      .filter(ee.Filter.calendarRange(1981, 2021, 'year'))
      .filter(ee.Filter.calendarRange(3, 9, 'month'))
      .select('precipitation');

    const sizeHist = rainfallHistorical.size().getInfo();
    console.log(`Historical Images found: ${sizeHist}`);

    if (sizeHist === 0) {
      console.log('No historical data found.');
      console.log('<answer>C1</answer>');
      return;
    }

    // 5. Calculate total rainfall for 2022
    const total2022 = rainfall2022.sum();
    const result2022 = total2022.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 5000,
      maxPixels: 1e9
    });

    const rain2022 = result2022.get('precipitation').getInfo();

    // Check pixel count
    const count2022 = total2022.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    console.log(`2022 Valid Pixels: ${count2022}`);

    if (count2022 === 0) {
      console.log('No valid pixels for 2022.');
      console.log('<answer>C2</answer>');
      return;
    }

    // 6. Calculate average total for historical period
    // Sum per year, then average across years
    const years = ee.List.sequence(1981, 2021);
    const yearlyTotals = years.map(function(year) {
      const yearlySum = chirps
        .filter(ee.Filter.calendarRange(year, year, 'year'))
        .filter(ee.Filter.calendarRange(3, 9, 'month'))
        .select('precipitation')
        .sum();
      return yearlySum;
    });

    const historicalMean = ee.ImageCollection(yearlyTotals).mean();
    const resultHist = historicalMean.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 5000,
      maxPixels: 1e9
    });

    const rainHist = resultHist.get('precipitation').getInfo();

    const countHist = historicalMean.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    console.log(`Historical Valid Pixels: ${countHist}`);

    if (countHist === 0) {
      console.log('No valid pixels for historical period.');
      console.log('<answer>C2</answer>');
      return;
    }

    // 7. Validation
    if (rain2022 === null || rainHist === null || 
        isNaN(rain2022) || isNaN(rainHist) ||
        rain2022 < 0 || rainHist < 0) {
      console.log('Invalid calculation results.');
      console.log('<answer>C3</answer>');
      return;
    }

    // 8. Print results and answer
    console.log(`2022 Total Rainfall: ${rain2022.toFixed(2)} mm`);
    console.log(`1981-2021 Avg Rainfall: ${rainHist.toFixed(2)} mm`);
    console.log(`Difference: ${(rain2022 - rainHist).toFixed(2)} mm`);

    if (rain2022 < rainHist) {
      console.log('Rainfall decreased in 2022.');
      console.log('<answer>A</answer>');
    } else {
      console.log('Rainfall did not decrease in 2022.');
      console.log('<answer>B</answer>');
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log('<answer>D</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
